package cryptosquare

import (
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lowercasing and removing non-alphanumeric
// characters), arranges it into a rectangle as square as possible, and
// returns the text read down the columns, with each column as a space-
// separated chunk padded with trailing spaces to fill the rectangle.
func Encode(pt string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(pt) {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(r)
		}
	}
	msg := b.String()
	n := len(msg)
	if n == 0 {
		return ""
	}

	c := 1
	for c*c < n {
		c++
	}
	r := (n + c - 1) / c

	chunks := make([]string, c)
	for j := 0; j < c; j++ {
		for i := 0; i < r; i++ {
			pos := i*c + j
			if pos < n {
				chunks[j] += msg[pos : pos+1]
			} else {
				chunks[j] += " "
			}
		}
	}
	return strings.Join(chunks, " ")
}

